    async saveRoute() {
      this.isSaving = true;
      const routeToSave = {
        start: this.start,
        end: this.end,
        waypoints: this.waypoints,
        // Save waypoints
        vehicle: this.vehicle,
        optimization: this.optimization,
        distance: this.distance,
