      this.end = saved.end;
      this.waypoints = saved.waypoints || ''; // Load waypoints
      this.vehicle = saved.vehicle;
      this.optimization = saved.optimization;
      this.routeNotes = saved.notes;
      this.timeAdjustment = saved.timeAdjustment || 0;
